// Extraer y validar datos de la app móvil
const body = $input.first().json.body || $input.first().json;

const imageData = body.image || '';
const avatar = body.avatar || 'professional-woman';
const voice = body.voice || 'female-warm';
const style = body.style || 'comercial';
const timestamp = body.timestamp || new Date().toISOString();

if (!imageData || !imageData.startsWith('data:image')) {
  throw new Error('No se recibió una imagen válida. Asegúrate de enviar un data URI (data:image/...).');
}

const base64Data = imageData.split(',')[1];
const mimeType = imageData.match(/data:(.*?);/)?.[1] || 'image/jpeg';

const avatarConfig = {
  'professional-woman': {
    name: 'Sofía',
    did_image_url: 'https://d-id-public-bucket.s3.us-west-2.amazonaws.com/rian.jpg',
    heygen_avatar_id: 'Abigail_standing_office_front',
    personality: 'una ejecutiva profesional, cálida y confiable',
    eleven_voice: 'EXAVITQu4vr4xnSDxMaL',
    heygen_voice_id: '2d5bcf07da7b4e7da3907f1cb96da03a'
  },
  'professional-man': {
    name: 'Carlos',
    did_image_url: 'https://d-id-public-bucket.s3.us-west-2.amazonaws.com/jack.jpg',
    heygen_avatar_id: 'Tyler-incasualsuit-20220721',
    personality: 'un consultor experto, serio pero accesible',
    eleven_voice: 'pqHfZKP75CvOlQylNhV4',
    heygen_voice_id: 'd7730e707328400085ef3f707f354f39'
  },
  'young-woman': {
    name: 'Ana',
    did_image_url: 'https://d-id-public-bucket.s3.us-west-2.amazonaws.com/amy.jpg',
    heygen_avatar_id: 'Kayla-incasualsuit-20220818',
    personality: 'una influencer tech, energética y moderna',
    eleven_voice: 'jBpfuIE2acCO8z3wKNLl',
    heygen_voice_id: 'c808f972df544a4286f03023e387c268'
  },
  'young-man': {
    name: 'Diego',
    did_image_url: 'https://d-id-public-bucket.s3.us-west-2.amazonaws.com/will.jpg',
    heygen_avatar_id: 'josh_lite3_20230714',
    personality: 'un emprendedor joven, directo y entusiasta',
    eleven_voice: 'TX3LPaxmHKxFdv7VOQHJ',
    heygen_voice_id: '26b00998bb19460098df90393b49e3df'
  }
};

const voiceConfig = {
  'female-warm': { id: 'EXAVITQu4vr4xnSDxMaL', heygen_id: '2d5bcf07da7b4e7da3907f1cb96da03a', name: 'Sara', stability: 0.6, similarity: 0.8 },
  'male-deep': { id: 'pqHfZKP75CvOlQylNhV4', heygen_id: 'd7730e707328400085ef3f707f354f39', name: 'Bill', stability: 0.7, similarity: 0.75 },
  'female-energetic': { id: 'jBpfuIE2acCO8z3wKNLl', heygen_id: 'c808f972df544a4286f03023e387c268', name: 'Gigi', stability: 0.5, similarity: 0.8 },
  'male-casual': { id: 'TX3LPaxmHKxFdv7VOQHJ', heygen_id: '26b00998bb19460098df90393b49e3df', name: 'Liam', stability: 0.55, similarity: 0.8 }
};

const styleConfig = {
  'comercial': { tone: 'profesional', duration: '30s', structure: 'Hook -> Benefits -> CTA' },
  'informativo': { tone: 'educativo', duration: '60s', structure: 'Intro -> Details -> Verdict' },
  'viral': { tone: 'dinámico', duration: '15s', structure: 'Hook -> Detail -> CTA' }
};

const config = avatarConfig[avatar] || avatarConfig['professional-woman'];
const voiceCfg = voiceConfig[voice] || voiceConfig['female-warm'];
const styleCfg = styleConfig[style] || styleConfig['comercial'];
const jobId = `job_${Date.now()}`;

return [{
  json: {
    jobId,
    imageBase64: base64Data,
    imageMimeType: mimeType,
    avatar: config,
    avatarKey: avatar,
    voice: voiceCfg,
    voiceKey: voice,
    style: styleCfg,
    styleKey: style,
    timestamp
  }
}];

// Construir request body para Anthropic Vision API
const prevData = $input.first().json;

const requestBody = {
  model: 'claude-sonnet-4-5-20250929',
  max_tokens: 1500,
  messages: [{
    role: 'user',
    content: [
      {
        type: 'image',
        source: {
          type: 'base64',
          media_type: prevData.imageMimeType,
          data: prevData.imageBase64
        }
      },
      {
        type: 'text',
        text: 'Analiza esta imagen de un producto y responde SOLAMENTE en JSON puro sin bloques de código.\n\nIdentifica:\n- Qué producto es\n- Marca (si es visible)\n- Categoría (electrónica, alimentos, ropa, hogar, belleza, etc.)\n- Colores principales\n- Material aparente\n- Características visibles destacadas\n- Público objetivo probable\n- Rango de precio estimado\n- 3 beneficios principales que un vendedor destacaría\n- 3 puntos de dolor que este producto resuelve\n\nFormato exacto:\n{"producto":"...","marca":"...","categoria":"...","colores":[],"material":"...","caracteristicas":[],"publico":"...","precioEstimado":"...","beneficios":[],"puntosDolor":[],"palabrasClave":[]}'
      }
    ]
  }]
};

return [{ json: { requestBody } }];

// Parsear respuesta de Anthropic API y combinar con datos originales
const prevData = $('⚙️ Validar y Configurar').first().json;
const apiResponse = $input.first().json;

let analysis;
try {
  let text = apiResponse.content?.[0]?.text || '';
  text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  analysis = JSON.parse(text);
} catch(e) {
  analysis = {
    producto: 'Producto innovador',
    marca: 'Marca Premium',
    categoria: 'general',
    colores: ['elegante'],
    material: 'alta calidad',
    caracteristicas: ['Diseño moderno', 'Alta calidad', 'Funcional'],
    publico: 'Profesionales exigentes',
    precioEstimado: 'Premium',
    beneficios: ['Mejora tu productividad', 'Diseño elegante', 'Durabilidad excepcional'],
    puntosDolor: ['Productos de baja calidad', 'Diseño aburrido', 'Poca durabilidad'],
    palabrasClave: ['premium', 'innovador', 'calidad']
  };
}

return [{ json: { ...prevData, analysis } }];

// Construir request body para Anthropic API (generación de guión)
const prevData = $input.first().json;

const prompt = `Eres un copywriter experto en videos de ventas y presentaciones de productos. Tu tarea es escribir un GUIÓN DE VIDEO para un avatar parlante que presenta un producto.

## DATOS DEL PRODUCTO:
${JSON.stringify(prevData.analysis, null, 2)}

## AVATAR:
- Nombre: ${prevData.avatar.name}
- Personalidad: ${prevData.avatar.personality}

## ESTILO DEL VIDEO:
- Tono: ${prevData.style.tone}
- Duración objetivo: ${prevData.style.duration}
- Estructura: ${prevData.style.structure}

## REGLAS:
1. El guión es SOLO lo que el avatar DICE en voz alta (no incluyas instrucciones de cámara ni escena)
2. Habla en primera persona como si fueras el avatar
3. Menciona el nombre del producto naturalmente
4. Usa lenguaje conversacional en español latinoamericano
5. Incluye al menos 2 beneficios concretos
6. Termina con un call-to-action claro
7. NO uses hashtags ni emojis en el guión
8. Adapta la extensión al estilo (viral=corto, comercial=medio, informativo=largo)
9. Cada oración debe ser natural para hablar en voz alta
10. Evita tecnicismos innecesarios

Responde SOLO con el JSON, sin bloques de código:
{"guion":"...","duracionEstimada":"...","hookInicial":"...","callToAction":"..."}`;

const requestBody = {
  model: 'claude-sonnet-4-5-20250929',
  max_tokens: 2000,
  messages: [{ role: 'user', content: prompt }]
};

return [{ json: { requestBody } }];

// Parsear guión generado por Anthropic API
const prevData = $('📊 Parsear Análisis').first().json;
const apiResponse = $input.first().json;

let script;
try {
  let text = apiResponse.content?.[0]?.text || '';
  text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  script = JSON.parse(text);
} catch(e) {
  const a = prevData.analysis;
  script = {
    guion: `Hola, soy ${prevData.avatar.name}. Hoy quiero presentarte algo increíble: ${a.producto}. Este producto está diseñado para ${a.publico} que buscan lo mejor. ${a.beneficios.join('. ')}. No te quedes sin el tuyo, te aseguro que va a cambiar tu experiencia por completo.`,
    duracionEstimada: '30 segundos',
    hookInicial: 'Hoy quiero presentarte algo increíble',
    callToAction: 'No te quedes sin el tuyo'
  };
}

return [{ json: { ...prevData, script } }];

// Extraer audio en base64 y construir data URI para los servicios de avatar
const prevData = $('📝 Parsear Guión').first().json;
const audioItem = $input.first();

let audioBase64 = '';
let audioDataUri = '';
try {
  const binaryData = audioItem.binary?.data;
  if (binaryData && binaryData.data) {
    audioBase64 = binaryData.data;
    audioDataUri = 'data:audio/mpeg;base64,' + audioBase64;
  }
} catch(e) {
  // Audio binary no disponible
}

if (!audioBase64) {
  throw new Error('ElevenLabs no generó audio. Verifica tu API key y créditos.');
}

return [{
  json: {
    ...prevData,
    audioBase64,
    audioDataUri,
    audioAvailable: true
  }
}];

// Polling D-ID hasta que el video esté listo
const talkId = $input.first().json.id;
if (!talkId) {
  throw new Error('D-ID no retornó un talk ID. Respuesta: ' + JSON.stringify($input.first().json).substring(0, 500));
}

const apiKey = $env.DID_API_KEY;
if (!apiKey) {
  throw new Error('Variable de entorno DID_API_KEY no configurada. Agrégala en Settings → Variables.');
}

const maxAttempts = 30;
let videoUrl = null;

for (let attempt = 1; attempt <= maxAttempts; attempt++) {
  const response = await fetch(`https://api.d-id.com/talks/${talkId}`, {
    headers: {
      'Authorization': `Basic ${apiKey}`,
      'Content-Type': 'application/json'
    }
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`D-ID polling HTTP ${response.status}: ${errorText.substring(0, 300)}`);
  }

  const data = await response.json();

  if (data.status === 'done' && data.result_url) {
    videoUrl = data.result_url;
    break;
  } else if (data.status === 'error') {
    throw new Error(`D-ID error: ${data.error?.description || JSON.stringify(data).substring(0, 300)}`);
  }

  await new Promise(r => setTimeout(r, 5000));
}

if (!videoUrl) {
  throw new Error('Timeout: D-ID no generó el video en 150 segundos.');
}

return [{ json: { videoUrl, service: 'd-id', talkId } }];

