// Polling HeyGen hasta que el video esté listo
const responseData = $input.first().json;
const videoId = responseData.data?.video_id;
if (!videoId) {
  throw new Error('HeyGen no retornó video_id. Respuesta: ' + JSON.stringify(responseData).substring(0, 500));
}

const apiKey = 'sk_V2_hgu_kP6rz6wz5GK_NNGDAotUHQU7UliQZW0q13vjXKbHH1fn';

const maxAttempts = 60;
let videoUrl = null;

for (let attempt = 1; attempt <= maxAttempts; attempt++) {
  const response = await fetch(`https://api.heygen.com/v1/video_status.get?video_id=${videoId}`, {
    headers: {
      'X-Api-Key': apiKey
    }
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`HeyGen polling HTTP ${response.status}: ${errorText.substring(0, 300)}`);
  }

  const data = await response.json();

  if (data.data?.status === 'completed' && data.data?.video_url) {
    videoUrl = data.data.video_url;
    break;
  } else if (data.data?.status === 'failed') {
    throw new Error(`HeyGen error: ${data.data?.error || JSON.stringify(data).substring(0, 300)}`);
  }

  await new Promise(r => setTimeout(r, 5000));
}

if (!videoUrl) {
  throw new Error('Timeout: HeyGen no generó el video en 300 segundos.');
}

return [{ json: { videoUrl, service: 'heygen', videoId } }];

// Merge final: tomar videoUrl de la rama que ejecutó (D-ID o HeyGen)
const videoData = $input.first().json;
const originalData = $('🎬 Preparar para Avatar').first().json;

return [{
  json: {
    jobId: originalData.jobId,
    videoUrl: videoData.videoUrl || 'No URL found',
    service: videoData.service || 'unknown',
    producto: originalData.analysis?.producto || 'Producto',
    avatar: originalData.avatar?.name || 'Avatar',
    estilo: originalData.styleKey || 'comercial',
    guion: originalData.script?.guion || '',
    duracion: originalData.script?.duracionEstimada || '',
    timestamp: new Date().toISOString(),
    status: 'completed'
  }
}];
